21	function assertApiSuccess(label: string, response: unknown): void {
22	  const result = response as { code?: number; msg?: string } | null;
23	  if (result && typeof result.code === "number" && result.code !== 0) {
24	    throw new Error(`${label}: ${result.msg || `code ${result.code}`}`);
25	  }
26	}
