28	function formatErrorBrief(error: unknown): string {
29	  if (error instanceof Error) {
30	    return error.message;
31	  }
32	  const obj = error as { code?: number; msg?: string } | null;
33	  if (obj && typeof obj.code === "number") {
34	    return `code=${obj.code} msg=${obj.msg || "unknown"}`;
35	  }
36	  return String(error);
37	}
