142	/**
143	 * M3 & m6: 上传图片到飞书开放平台获取 image_key（image_type=message）。
144	 * 仅单一对象入参签名。
145	 * 安全策略：
146	 * - 只接受 https:// URL，超时 5000ms，Content-Type 须为 image/，大小 ≤10MB
147	 * - 拦截私网 / 环回 / link-local 地址（SSRF 防御）
148	 * - 本机路径只允许在 ~/.trellis/ 或当前 workspacePath 下读取，其余不读盘
149	 * - 失败或不合规时返回空字符串，触发上层降级为 [图片] alt 文本
150	 */
151	export async function uploadLarkImage(options: UploadLarkImageOptions): Promise<string> {
152	  const { client, image, workspacePath } = options;
153	  const MAX_IMAGE_SIZE = 10 * 1024 * 1024; // 10MB
154	
155	  let buffer: Buffer;
156	
157	  if (Buffer.isBuffer(image)) {
158	    if (image.length > MAX_IMAGE_SIZE) {
159	      console.warn("[lark] 图片大小超出 10MB 限制");
160	      return "";
161	    }
162	    buffer = image;
163	  } else if (typeof image === "string") {
164	    const src = image.trim();
165	    if (src.startsWith("img_")) {
166	      return src;
167	    }
168	
169	    // scheme 判断不分大小写：`HTTPS://…` 是合规 URL，落到本机路径分支会被白名单无声拒掉（复审 n5）。
170	    const scheme = src.toLowerCase();
171	    if (scheme.startsWith("http://")) {
172	      console.warn("[lark] 拒绝上传明文 http 图片:", src);
173	      return "";
174	    }
175	
176	    if (scheme.startsWith("https://")) {
177	      let parsed: URL;
178	      try {
179	        parsed = new URL(src);
180	      } catch {
181	        console.warn("[lark] 无效的图片 URL:", src);
182	        return "";
183	      }
184	
185	      if (isPrivateOrLoopbackHost(parsed.hostname)) {
186	        console.warn("[lark] 拒绝访问私网/环回地址:", parsed.hostname);
187	        return "";
188	      }
189	
190	      try {
