  now: number;
}): void {
  const { bot, message, turn, sent } = args;
  const threadId = message.chatType === "group" ? sent.threadId ?? message.threadId : null;
  if (sent.messageId) {
    recordLarkOutbox({
      messageId: sent.messageId,
